package com.citacloud.springboot.contacloud.app.services;
import com.citacloud.springboot.contacloud.app.dto.*; import com.citacloud.springboot.contacloud.app.models.*; import com.citacloud.springboot.contacloud.app.repositories.*; import com.citacloud.springboot.contacloud.app.security.*;
import org.springframework.data.domain.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import java.math.*; import java.time.OffsetDateTime; import java.util.*; import java.util.function.Function; import java.util.stream.Collectors;
@Service
public class RecuentoCajaService {
 private static final int MAX_QTY=1_000_000; private static final String OP="CASH_COUNT_CREATE";
 private final CashRegisterSessionRepository sesiones; private final FinancialMovementRepository movimientos; private final DenominacionCajaRepository denominaciones; private final RecuentoCajaRepository recuentos; private final DetalleRecuentoCajaRepository detalles; private final AuditoriaService auditoria; private final IdempotentOperationService idempotencia; private final JdbcTemplate jdbc;
 public RecuentoCajaService(CashRegisterSessionRepository s,FinancialMovementRepository m,DenominacionCajaRepository d,RecuentoCajaRepository r,DetalleRecuentoCajaRepository de,AuditoriaService a,IdempotentOperationService i,JdbcTemplate j){sesiones=s;movimientos=m;denominaciones=d;recuentos=r;detalles=de;auditoria=a;idempotencia=i;jdbc=j;}
 @Transactional(readOnly=true) @PreAuthorize("hasAuthority('recuentos_caja.crear')")
 public PreparacionRecuentoCajaDto preparar(UUID sesionId){SesionCaja s=sesionAbierta(sesionId,false);List<DenominacionCaja> ds=catalogo(s);var p=TenantContext.principalActual();return new PreparacionRecuentoCajaDto(s.getId(),s.getCaja().getNombre(),s.getSucursal().getNombre(),s.getMonedaId(),s.getMoneda().getCodigoIso(),s.getMoneda().getSimbolo(),OffsetDateTime.now(),p.nombre(),ds.stream().map(d->new PreparacionRecuentoCajaDto.Denominacion(d.getId(),d.getValor(),d.getTipo(),d.getOrden())).toList());}
 @Transactional @PreAuthorize("hasAuthority('recuentos_caja.crear')")
 public RecuentoCajaDto guardar(GuardarRecuentoCajaInput input){if(input==null||input.sesionId()==null||input.idempotencia()==null)throw new ReglaNegocioException("No fue posible identificar el recuento de caja.");var p=TenantContext.principalActual();UUID e=EmpresaContext.requerirEmpresaId();String fp=CommandFingerprint.sha256(input);var start=idempotencia.begin(p.tenantId(),e,OP,input.idempotencia(),fp);if(start.replay())return obtenerInterno(start.resultId());
  SesionCaja s=sesionAbierta(input.sesionId(),true);List<DenominacionCaja> catalogo=catalogo(s);Map<UUID,DenominacionCaja> permitidas=catalogo.stream().collect(Collectors.toMap(DenominacionCaja::getId,Function.identity()));Map<UUID,Integer> cantidades=validar(input.cantidades(),permitidas);BigDecimal contado=cantidades.entrySet().stream().map(x->permitidas.get(x.getKey()).getValor().multiply(BigDecimal.valueOf(x.getValue()))).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal esperado=resumen(s);OffsetDateTime now=OffsetDateTime.now();String numero=siguienteNumero(p.tenantId(),e);RecuentoCaja r=recuentos.saveAndFlush(new RecuentoCaja(p.tenantId(),e,numero,s,now,p.usuarioId(),esperado,contado,nota(input.observacion()),input.idempotencia()));int orden=1;for(DenominacionCaja d:catalogo){int q=cantidades.getOrDefault(d.getId(),0);detalles.save(new DetalleRecuentoCaja(p.tenantId(),e,r.getId(),d,q,orden++));}detalles.flush();auditoria.registrar("CASH_COUNT_CREATED","RecuentoCaja",r.getId(),"{\"sesionId\":\""+s.getId()+"\",\"esperado\":"+esperado+",\"contado\":"+contado+",\"diferencia\":"+r.getDiferencia()+"}");idempotencia.complete(p.tenantId(),e,OP,input.idempotencia(),"RecuentoCaja",r.getId());return dto(r,detalles.findAllByRecuentoIdOrderByOrdenAsc(r.getId()));}
 @Transactional(readOnly=true) @PreAuthorize("hasAuthority('recuentos_caja.ver')") public RecuentoCajaDto obtener(UUID id){return obtenerInterno(id);}
 @Transactional(readOnly=true) @PreAuthorize("hasAuthority('recuentos_caja.ver')") public Page<RecuentoCajaDto> historial(UUID sesion,int pagina){if(pagina<0)throw new ReglaNegocioException("Paginación inválida.");var p=TenantContext.principalActual();SesionCaja s=sesionSegura(sesion);return recuentos.historial(p.tenantId(),EmpresaContext.requerirEmpresaId(),s.getId(),PageRequest.of(pagina,5,Sort.by(Sort.Direction.DESC,"contadoEn","id"))).map(r->dto(r,List.of()));}
 private RecuentoCajaDto obtenerInterno(UUID id){var p=TenantContext.principalActual();RecuentoCaja r=recuentos.findByIdAndTenantIdAndEmpresaId(id,p.tenantId(),EmpresaContext.requerirEmpresaId()).orElseThrow(()->new RecursoNoEncontradoException("Recuento de caja no encontrado."));if(!EmpresaContext.permiteSucursal(r.getSucursalId()))throw new RecursoNoEncontradoException("Recuento de caja no encontrado.");return dto(r,detalles.findAllByRecuentoIdOrderByOrdenAsc(id));}
 private SesionCaja sesionAbierta(UUID id,boolean lock){var p=TenantContext.principalActual();SesionCaja s=(lock?sesiones.bloquear(id,p.tenantId(),EmpresaContext.requerirEmpresaId()):sesiones.findByIdAndTenantIdAndEmpresaId(id,p.tenantId(),EmpresaContext.requerirEmpresaId())).orElseThrow(()->new ReglaNegocioException("La caja debe estar abierta para realizar un recuento."));if(s.getStatus()!=EstadoSesionCaja.OPEN||!EmpresaContext.permiteSucursal(s.getSucursalId())||!s.getAbiertoPor().equals(p.usuarioId()))throw new ReglaNegocioException("La caja debe estar abierta para realizar un recuento.");return s;}
 private SesionCaja sesionSegura(UUID id){return sesionAbierta(id,false);}
 private List<DenominacionCaja> catalogo(SesionCaja s){List<DenominacionCaja> ds=denominaciones.findAllByTenantIdAndEmpresaIdAndMonedaIdAndActiveTrueOrderByOrdenAsc(s.getTenantId(),s.getEmpresaId(),s.getMonedaId());if(ds.isEmpty())throw new ReglaNegocioException("La configuración de denominaciones de la moneda no está disponible.");return ds;}
 private Map<UUID,Integer> validar(List<GuardarRecuentoCajaInput.Cantidad> lineas,Map<UUID,DenominacionCaja> permitidas){Map<UUID,Integer> r=new HashMap<>();if(lineas==null)lineas=List.of();for(var l:lineas){if(l==null||l.denominacionId()==null||!permitidas.containsKey(l.denominacionId()))throw new ReglaNegocioException("La denominación seleccionada no es válida.");if(l.cantidad()==null||l.cantidad()<0||l.cantidad()>MAX_QTY)throw new ReglaNegocioException("La cantidad debe ser un entero entre 0 y "+MAX_QTY+".");if(r.put(l.denominacionId(),l.cantidad())!=null)throw new ReglaNegocioException("No se puede repetir una denominación.");}return r;}
 private BigDecimal resumen(SesionCaja s){BigDecimal saldo=s.getFondoInicial();for(MovimientoFinanciero m:movimientos.movimientosValidosSesion(s.getTenantId(),s.getEmpresaId(),s.getId()))if(m.getMedioPago()==MedioPagoMovimiento.CASH)saldo=m.getTipoMovimiento()==TipoMovimientoFinanciero.INCOME?saldo.add(m.getMonto()):saldo.subtract(m.getMonto());return saldo;}
 private String siguienteNumero(UUID t,UUID e){jdbc.update("insert into cash_count_sequence(tenant_id,empresa_id,current_value) values (?,?,0) on conflict do nothing",t,e);Long n=jdbc.queryForObject("update cash_count_sequence set current_value=current_value+1 where tenant_id=? and empresa_id=? returning current_value",Long.class,t,e);return "RCJ-"+String.format("%06d",n);}
 private static String nota(String s){if(s==null||s.isBlank())return null;String n=s.trim();if(n.length()>500)throw new ReglaNegocioException("La observación excede 500 caracteres.");return n;}
 private static RecuentoCajaDto dto(RecuentoCaja r,List<DetalleRecuentoCaja> ds){return new RecuentoCajaDto(r.getId(),r.getNumero(),r.getSesionId(),r.getSesion()==null?null:r.getSesion().getCodigoVisible(),r.getCaja().getNombre(),r.getSucursal().getNombre(),r.getMoneda().getCodigoIso(),r.getMoneda().getSimbolo(),r.getContadoEn(),r.getUsuario().getNombre(),r.getEsperado(),r.getContado(),r.getDiferencia(),r.getResult(),r.getObservation(),ds.stream().map(d->new RecuentoCajaDto.Detalle(d.getDenomination(),d.getTipo(),d.getQuantity(),d.getSubtotal())).toList());}
}
